volatile LONG g_freshArmed = 0;
// Peak-hold per window (INV-8 - a mean aliases a two-frame jump).
float  g_freshD8Pk      = 0.0f;   // |composed(8)  - cached(8) |  anchor staleness
float  g_freshD48Pk     = 0.0f;   // |composed(48) - cached(48)|  shoulder staleness
float  g_freshCachedPk  = 0.0f;   // step of the CACHED separation   <- today
float  g_freshFreshPk   = 0.0f;   // step of the COMPOSED separation <- the rig WOULD see
float  g_freshPrevCached[3] = {};
float  g_freshPrevFresh[3]  = {};
