// The angle between two rotations, in degrees. One definition, used for every
// "how far apart are these two poses" question below.
float Mat3AngleBetween(const float* a, const float* b)
{
    float at[9], r[9];
    Mat3Transpose(a, at);
    Mat3Mul(at, b, r);
    float c = (r[0] + r[4] + r[8] - 1.0f) * 0.5f;
    if (c >  1.0f) { c =  1.0f; }
    if (c < -1.0f) { c = -1.0f; }
    return acosf(c) * 57.2957795f;
}

