volatile LONG64 g_hookCalls = 0, g_hookFiltered = 0, g_hookHidden[2] = {}, g_hookByClimb[2] = {}, g_hookByTail[2] = {},
                g_hookBySwap[2] = {}, g_hookByGrab[2] = {}, g_hookByLid[2] = {};
